using System;using System.Drawing;using System.Windows.Forms;
namespace EanEtikety {
public partial class MainForm {
 void AddBarcodeObject(){var settings=Read();if(settings.HideBarcode){ChangeDocument(s=>s.HideBarcode=false);preview.SelectElement(-1);return;}var symbol=new SymbolItem{X=settings.BarX+2,Y=settings.BarY+2,Width=settings.BarWidth,Height=Engine.BarcodeHeight(settings),Rotation=settings.BarRotation,Code=BarcodeContent.From(settings)};EditBarcodeObject(-2,symbol);}
 void EditBarcodeObject(int index,SymbolItem symbol){using(var f=FeatureForm("Čiarový kód",500,620)){var p=FeatureStack(f);var types=new string[MoreBarcodes.Kinds.Length];for(int i=0;i<types.Length;i++)types[i]=MoreBarcodes.Name(MoreBarcodes.Kinds[i]);var type=Choice(p,"Typ kódu",types,Array.IndexOf(MoreBarcodes.Kinds,symbol.Code.Kind));var data=Input(p,"Obsah kódu",symbol.Code.Ean);var show=Check(p,"Zobraziť číslice",symbol.Code.Digits);var gs1=Check(p,"GS1-128",symbol.Code.Gs1Mode);var ai=new DataGridView{Height=220,AutoGenerateColumns=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};ai.Columns.Add("ai","AI");ai.Columns.Add("data",Loc.T("Dáta"));foreach(var value in symbol.Code.ApplicationIdentifiers)ai.Rows.Add(value.AI,value.Data);StackAdd(p,ai);StackAdd(p,new Label{Text=Loc.T("Poradie riadkov určuje poradie identifikátorov GS1."),AutoSize=true,MaximumSize=new Size(430,0)});AddAccept(f,p,delegate{ai.EndEdit();var code=symbol.Code;code.Kind=MoreBarcodes.Kinds[type.SelectedIndex];code.Ean=data.Text;code.Digits=show.Checked;code.Gs1Mode=gs1.Checked&&code.Kind==128;code.ApplicationIdentifiers.Clear();foreach(DataGridViewRow row in ai.Rows)if(!row.IsNewRow)code.ApplicationIdentifiers.Add(new AiValue{AI=Convert.ToString(row.Cells[0].Value),Data=Convert.ToString(row.Cells[1].Value)});Engine.Validate(code.Settings());ChangeDocument(s=>{if(index<=-3)s.Symbols[-3-index]=symbol;else{if(s.Symbols.Count>=20)throw new InvalidOperationException(Loc.T("Najviac 20 symbolov."));s.Symbols.Add(symbol);}});preview.SelectElement(index<=-3?index:-3-symbols.Count+1);});f.ShowDialog(this);}}
}
}
